const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Córdoba Airport, Argentina (most likely - main international airport)
  const cordobaAirport = ee.Geometry.Point([-64.2083, -31.3236]);

  // Date range for April 26, 2023
  const startDate = '2023-04-26';
  const endDate = '2023-04-27';

  // Get ERA5-Land hourly temperature data (2m air temperature)
  let tempCollection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(cordobaAirport)
    .select('temperature_2m');

  const collectionSize = tempCollection.size().getInfo();
  console.log(`ERA5-Land images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No ERA5-Land data available. Trying MODIS LST...');

    // Fallback to MODIS Terra LST
    tempCollection = ee.ImageCollection('MODIS/061/MOD11A1')
      .filterDate(startDate, endDate)
      .filterBounds(cordobaAirport)
      .select('LST_Day_1km');

    const modisSize = tempCollection.size().getInfo();
    console.log(`MODIS images found: ${modisSize}`);

    if (modisSize === 0) {
      console.log('No temperature data available for this date.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Get maximum temperature across all hours/images
  const maxTemp = tempCollection.max();

  // Calculate max temperature at airport location
  const result = maxTemp.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: cordobaAirport,
    scale: 11000,
    maxPixels: 1e9
  });

  const tempValue = result.values().get(0).getInfo();

  if (tempValue === null || tempValue === undefined) {
    console.log('Temperature calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert from Kelvin to Celsius (ERA5-Land is in Kelvin)
  // MODIS LST is in Kelvin * 0.02, need to convert
  let tempCelsius;
  if (tempValue > 200) {
    // ERA5-Land format (Kelvin)
    tempCelsius = tempValue - 273.15;
  } else {
    // MODIS format (Kelvin * 0.02)
    tempCelsius = (tempValue * 0.02) - 273.15;
  }

  console.log(`Maximum temperature on April 26, 2023: ${tempCelsius.toFixed(2)}°C`);

  // Validate reasonable temperature range
  if (tempCelsius < -50 || tempCelsius > 60) {
    console.log('Temperature value outside reasonable range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if temperature exceeded 40°C
  if (tempCelsius > 40) {
    console.log('Temperature exceeded 40°C.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Temperature did not exceed 40°C.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
